    public static function svg(string $name, string $class = 'icon'): string
    {
        $inner = self::ICONS[$name] ?? self::ICONS['circle-dot'];
        return '<svg class="' . htmlspecialchars($class, ENT_QUOTES) . '" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $inner . '</svg>';
    }

    public static function has(string $name): bool
    {
        return isset(self::ICONS[$name]);
    }
